import type { RequestHandler } from '@builder.io/qwik-city';
import { createApiKey, listApiKeys } from '~/lib/db';

export const onPost: RequestHandler = async (event) => {
  try {
    const body = (await event.parseBody()) as { name?: string } | null;
    if (!body || typeof body.name !== 'string' || body.name.trim() === '') {
      event.json(400, { error: 'Name is required' });
      return;
    }

    const { row, plainTextKey } = createApiKey(body.name.trim());

    event.json(201, {
      id: row.id,
      name: row.name,
      prefix: row.key_prefix,
      key: plainTextKey,
      status: row.status,
      created_at: row.created_at,
    });
  } catch (error: any) {
    event.json(500, { error: error.message || 'Internal Server Error' });
  }
};

export const onGet: RequestHandler = async (event) => {
  try {
    const keys = listApiKeys();
    const response = keys.map((k) => ({
      id: keys.length > 0 ? k.id : undefined, // just to be safe, but k.id is always there
      name: k.name,
      prefix: k.key_prefix,
      status: k.status,
      created_at: k.created_at,
    })).filter(k => k.id !== undefined);

    event.json(200, response);
  } catch (error: any) {
    event.json(500, { error: error.message || 'Internal Server Error' });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { revokeApiKey } from '~/lib/db';

export const onPost: RequestHandler = async (event) => {
  try {
    const id = parseInt(event.params.id, 10);
    if (isNaN(id)) {
      event.json(404, { error: 'Key not found' });
      return;
    }

    const success = revokeApiKey(id);
    if (!success) {
      event.json(404, { error: 'Key not found' });
      return;
    }

    event.json(200, {
      success: true,
      message: 'API key revoked successfully',
    });
  } catch (error: any) {
    event.json(500, { error: error.message || 'Internal Server Error' });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import { verifyApiKey } from '~/lib/db';

export const onGet: RequestHandler = async (event) => {
  try {
    const apiKey = event.request.headers.get('x-api-key') || event.request.headers.get('X-API-Key');
    if (!apiKey) {
      event.json(401, { error: 'Unauthorized' });
      return;
    }

    const isValid = verifyApiKey(apiKey);
    if (!isValid) {
      event.json(401, { error: 'Unauthorized' });
      return;
    }

    event.json(200, {
      message: 'Hello, authenticated developer!',
    });
  } catch (error: any) {
    event.json(500, { error: error.message || 'Internal Server Error' });
  }
};

:root {
  --primary: #0066cc;
  --primary-hover: #0052a3;
  --bg: #f5f7fa;
  --card-bg: #ffffff;
  --text: #1a202c;
  --text-muted: #718096;
  --border: #e2e8f0;
  --success: #38a169;
  --success-bg: #f0fff4;
  --danger: #e53e3e;
  --danger-bg: #fff5f5;
}

