  max-width: 1000px;
  margin: 0 auto;
  padding: 40px 20px;
}

.header {
  margin-bottom: 30px;
}

.header h1 {
  margin: 0 0 10px 0;
  font-size: 2.5rem;
  font-weight: 800;
  color: #1a202c;
}

.header p {
  margin: 0;
  color: var(--text-muted);
  font-size: 1.1rem;
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 24px;
  margin-bottom: 30px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
}

.card-title {
  margin: 0 0 20px 0;
  font-size: 1.5rem;
  font-weight: 700;
  color: #2d3748;
}

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  font-weight: 600;
  font-size: 0.95rem;
  color: #4a5568;
}

.input-control {
  width: 100%;
  padding: 12px 16px;
  font-size: 1rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  box-sizing: border-box;
  transition: border-color 0.2s;
}

.input-control:focus {
  outline: none;
  border-color: var(--primary);
}

.btn {
  display: inline-block;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  border: none;
  transition: background-color 0.2s;
}

.btn-primary {
  background-color: var(--primary);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-danger {
  background-color: var(--danger);
  color: white;
  padding: 8px 16px;
  font-size: 0.9rem;
}

.btn-danger:hover {
  background-color: #c53030;
}

.btn-danger:disabled {
  background-color: #cbd5e0;
  cursor: not-allowed;
}

.alert {
  padding: 20px;
  border-radius: 8px;
  margin-bottom: 30px;
  border: 1px solid transparent;
}

.alert-success {
  background-color: var(--success-bg);
  border-color: #c6f6d5;
  color: #22543d;
}

.alert-title {
  font-weight: 700;
  font-size: 1.2rem;
  margin-top: 0;
  margin-bottom: 10px;
}

.alert-message {
  font-size: 1rem;
  margin-bottom: 15px;
}

