  align-items: center;
  background: white;
  border: 1px solid #c6f6d5;
  padding: 12px 16px;
  border-radius: 6px;
  font-family: monospace;
  font-size: 1.1rem;
  font-weight: bold;
  word-break: break-all;
  margin-bottom: 15px;
}

.key-display {
  flex-grow: 1;
}

.copy-btn {
  background: #edf2f7;
  border: 1px solid var(--border);
  padding: 6px 12px;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
  font-family: sans-serif;
  margin-left: 10px;
}

.copy-btn:hover {
  background: #e2e8f0;
}

