  background-color: #c6f6d5;
  color: #22543d;
}

.badge-revoked {
  background-color: #fed7d7;
  color: #742a2a;
}

.table-responsive {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

th, td {
  padding: 16px;
  border-bottom: 1px solid var(--border);
}

th {
  font-weight: 700;
  color: #4a5568;
  background-color: #f7fafc;
}

